#pragma once

/*
 * LPC546xx GPIO numbering.
 *
 * Six ports of 32 pins, spelled the way NXP's user manual and this project's
 * pin mapping spell them, so P1_18 here is P1_18 there. LPC_LINE comes from the
 * family's hal_pal_lld.h and packs the port and pad into one ioline_t.
 *
 * This overrides QMK's default pin names, which are STM32's: those build a line
 * from a GPIO peripheral base address, where this part uses a port number.
 *
 * Not every pin below is bonded out on every package. The ones this project
 * actually uses are in docs/pin-mapping.md.
 */

